/// Where a subpath's colour comes from.
///
/// The same three answers the iced file gives, because they are properties of
/// the reference's SVGs rather than of the toolkit: `currentColor` is what
/// almost every shape in the set asks for, a literal is a shape painted red or
/// white on purpose, and a `var(--token)` is one the shell resolves.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Ink {
    /// `currentColor`: the colour of whatever the icon is drawn in.
    Inherit,
    /// A literal the reference wrote out.
    Fixed(u8, u8, u8, u8),
    /// A `var(--token)` the reference names.
    Token(&'static str),
}

impl Ink {
    /// The colour this shape is, given what the caller is drawing with.
    pub fn resolve(self, inherit: Color32) -> Color32 {
        match self {
            Ink::Inherit => inherit,
            Ink::Fixed(r, g, b, a) => Color32::from_rgba_unmultiplied(r, g, b, a),
            // A token the shell has not been taught yet is drawn in the ink it
            // would have had anyway, which is visible rather than invisible.
            Ink::Token(_) => inherit,
        }
    }
}

/// One drawable piece of an icon: a single polyline and how to paint it.
///
/// This is one *subpath*, not one SVG element. An element with three subpaths
/// is three of these, because a `PathShape` cannot hold two -- see the module
/// documentation. The iced file's `Element` is the element-level record; this
/// is the shape-level one.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Subpath {
    /// The polyline, in the icon's own view box, as x/y pairs.
    pub points: &'static [(f32, f32)],
    /// Whether it closes back to its first point. True for every filled one.
    pub closed: bool,
    /// Stroke width in view-box units, before the fit scale is applied.
    pub stroke_width: f32,
    /// Whether this is filled rather than stroked.
    pub filled: bool,
    /// Where its colour comes from.
    pub ink: Ink,
    /// The element's own `opacity`, which multiplies whatever ink it gets.
    pub opacity: f32,
}

