/// Where a glyph's view box lands inside a rectangle: a uniform scale and the
/// offset its top-left corner takes.
///
/// The iced side returns `(scale, Vector)` from `icon::fit`; this is that pair
/// as one value, so a caller cannot pass the scale without the offset.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Fit {
    /// View-box units to points.
    pub scale: f32,
    /// Where the view box's top-left corner lands, relative to the origin.
    pub offset: Vec2,
}

/// How the spare space is split around the glyph: half each side, `xMidYMid`.
///
/// This is the constant `icon::fit` on the iced side also uses -- its offset is
/// `(size - drawn) * 0.5` -- and it is the SVG default, not a choice this port
/// made: none of the 441 SVGs declares `preserveAspectRatio`, so all of them
/// take `xMidYMid meet`. `meet` is the `min` of the two axis scales in [`fit`];
/// `xMid`/`yMid` are this 0.5.
pub const FIT_CENTRE: f32 = 0.5;

/// Where a glyph's view box lands inside `rect`: uniform scale, centred.
///
/// The scale is `min(rect.width / view_box.width, rect.height / view_box.height)`
/// -- `meet`, so the whole icon is visible -- and the glyph is centred in the
/// rectangle. For the square rectangles a control actually hands an icon, this
/// is `icon::fit`'s answer exactly; for a non-square one it centres in the whole
/// rectangle rather than in the largest square at its top-left, which is what
/// `fits into rect` has to mean.
///
/// A rectangle with no room in it -- a widget the layout gave zero pixels, which
/// happens on the frame a panel collapses -- gives the iced side's degenerate
/// answer: scale 1, no offset. Drawing at scale 1 into a zero-sized clip is
/// invisible, and it is not a panic or a division by zero.
pub fn fit(glyph: Glyph, rect: Rect) -> Fit {
    let (width, height) = glyph.view_box();
    let size = rect.width().min(rect.height());
    if width <= 0.0 || height <= 0.0 || size <= 0.0 {
        return Fit {
            scale: 1.0,
            offset: Vec2::ZERO,
        };
    }
    let scale = (size / width).min(size / height);
    let drawn = Vec2::new(width * scale, height * scale);
    Fit {
        scale,
        offset: rect.min.to_vec2() + (rect.size() - drawn) * FIT_CENTRE,
    }
}

/// The shapes for one glyph, ready for `Painter::add`.
///
/// Coordinates are screen points: the view box has been scaled by `fit.scale`
/// and moved by `fit.offset`. Stroke widths are scaled by the same factor, in
/// the same place, because epaint strokes the points it is given at the width
/// it is given -- it does not scale a stroke with anything -- so an icon at
/// 20 px would otherwise carry a 24 px icon's 2-unit pen and every edge would
/// be a fifth too heavy.
///
/// One `Shape` per [`Subpath`], and no more: the vector is pre-sized, and each
/// path's points are written straight into a vector sized for them.
pub fn parts(glyph: Glyph, fit: Fit, ink: Color32) -> Vec<Shape> {
    let subpaths = glyph.subpaths();
    let mut shapes = Vec::with_capacity(subpaths.len());
    for subpath in subpaths {
        let mut points = Vec::with_capacity(subpath.points.len());
        points.extend(subpath.points.iter().map(|&(x, y)| {
            Pos2::new(x.mul_add(fit.scale, fit.offset.x), y.mul_add(fit.scale, fit.offset.y))
        }));
        let resolved = subpath.ink.resolve(ink);
        let color = if subpath.opacity >= 1.0 {
            resolved
        } else {
            resolved.gamma_multiply(subpath.opacity)
        };
        let shape = if subpath.filled {
            // A fill closes itself; the stroke is the empty one, so epaint does
            // not also outline what it filled.
            PathShape::convex_polygon(points, color, PathStroke::NONE)
        } else if subpath.closed {
            PathShape::closed_line(
                points,
                PathStroke::new(subpath.stroke_width * fit.scale, color),
            )
        } else {
            PathShape::line(points, PathStroke::new(subpath.stroke_width * fit.scale, color))
        };
        shapes.push(Shape::Path(shape));
    }
    shapes
}

/// One glyph into `rect`, in `ink`, fitted and centred.
///
/// This is the plain call: build the shapes, hand them to the painter as one
/// `Shape::Vec` entry. [`cached`] is the same drawing with the built shapes kept
/// between frames.
pub fn draw(painter: &Painter, glyph: Glyph, rect: Rect, ink: Color32) {
    let shapes = parts(glyph, fit(glyph, rect), ink);
    painter.add(Shape::Vec(shapes));
}

/// How many built glyphs the cache keeps before it starts again from empty.
///
/// A screen does not hold more than this many distinct icons, and an icon whose
/// position changes every frame misses anyway, so a larger cache would only
/// keep shapes nobody is going to ask for. Clearing wholesale rather than
/// evicting one entry is deliberate: it bounds both the memory and the work,
/// and the alternative is a clock hand over a vector for no measured gain.
const CACHE_LIMIT: usize = 256;

/// Everything that can change a drawn glyph, as bits so it can be a hash key.
///
/// The position is in here as well as the size, because the shapes are baked in
/// screen coordinates: an icon that has moved is a different set of points.
/// `f32` is not `Eq`, so the three floats are compared by their bits -- two
/// offsets differing in the last bit are two different pictures anyway.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
struct CacheKey {
    glyph: Glyph,
    scale: u32,
    offset: [u32; 2],
    ink: [u8; 4],
}

/// One cache entry: the key it was built from, and the shapes it built.
struct CacheEntry {
    key: CacheKey,
    shapes: Vec<Shape>,
}

thread_local! {
    /// The recently built glyphs, per thread.
    ///
    /// `RefCell` rather than a `Mutex`: an egui context is driven by one thread,
    /// and a lock around a per-frame read would be a lock taken per icon to
    /// protect against something the toolkit does not do.
    static SHAPES: RefCell<Vec<CacheEntry>> = RefCell::new(Vec::new());
}

/// The key a glyph draws under. Split out so a test can hold it: a cache that
/// kept serving shapes after the size, the position or the ink changed would be
/// a stale picture nothing renders wrongly enough to notice.
fn cache_key(glyph: Glyph, fit: Fit, ink: Color32) -> CacheKey {
    CacheKey {
        glyph,
        scale: fit.scale.to_bits(),
        offset: [fit.offset.x.to_bits(), fit.offset.y.to_bits()],
        ink: ink.to_array(),
    }
}

/// The shapes for `key`, from the cache or built and then kept.
fn cached_shapes(key: CacheKey, glyph: Glyph, fit: Fit, ink: Color32) -> Vec<Shape> {
    SHAPES.with(|cache| {
        let mut cache = cache.borrow_mut();
        if let Some(entry) = cache.iter().find(|entry| entry.key == key) {
            // A hit: clone the built shapes. That is a copy of the points plus
            // the per-path vector headers, with no arithmetic and no colour
            // resolution -- cheaper than the build it replaces, and it is what
            // the painter needs to own its shapes.
            return entry.shapes.clone();
        }
        let shapes = parts(glyph, fit, ink);
        if cache.len() >= CACHE_LIMIT {
            cache.clear();
        }
        cache.push(CacheEntry {
            key,
            shapes: shapes.clone(),
        });
        shapes
    })
}

/// One glyph into `rect`, in `ink`, with the built shapes kept between frames.
///
/// Draw this instead of [`draw`] wherever the icon is not moving: a rail, a
/// button, a header. The first frame builds and stores; later frames hand egui a
/// clone of the stored shapes. An icon that *is* moving -- a row scrolling under
/// the pointer -- misses every frame, because the position is part of the key,
/// and pays the same build `draw` would have paid. That is not a regression, it
/// is the reason the cache cannot be the only entry point.
///
/// Returns the index the shapes were added at, for a caller that wants to
/// replace them later with `Painter::set`.
pub fn cached(painter: &Painter, glyph: Glyph, rect: Rect, ink: Color32) -> ShapeIdx {
    let fit = fit(glyph, rect);
    let shapes = cached_shapes(cache_key(glyph, fit, ink), glyph, fit, ink);
    painter.add(Shape::Vec(shapes))
}

